import java.sql.*;import java.nio.file.*;import java.util.*;import com.alibaba.fastjson2.*;
public class UnicodeRoundtrip{
 public static void main(String[]args)throws Exception{Path out=Paths.get(args[1]);Files.createDirectories(out);String table=args[2];JSONObject receipt=new JSONObject();try(Connection c=DriverManager.getConnection(args[0],"root","")){if(args.length>3)try(Statement s=c.createStatement()){s.execute("SET NAMES utf8mb4 COLLATE utf8mb4_bin");}try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT @@character_set_client,@@character_set_connection,@@character_set_results,@@collation_connection")){r.next();receipt.put("session",LittleXSql.obj("client",r.getString(1),"connection",r.getString(2),"results",r.getString(3),"collation",r.getString(4)));}receipt.put("driver_encoding",c.getClass().getMethod("getEncoding").invoke(c));try(Statement s=c.createStatement()){s.execute("CREATE TABLE "+table+" LIKE anchors");}JSONArray rows=new JSONArray();for(String id:Arrays.asList("023b071b-4811-4687-9654-585c1a4c7fe8","1d39d78d-9f12-4472-a32c-55a00f563177")){try(PreparedStatement p=c.prepareStatement("SELECT id,kind,arch_type,arch_module,fingerprint,root_id,src,dst,undirected,props,src_type,dst_type,seq,HEX(JSON_UNQUOTE(JSON_EXTRACT(props,'$.archetype.content'))) FROM _pristine_anchors WHERE id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){r.next();String raw=r.getString(10);JSONObject props=JSON.parseObject(raw);String serialized=props.toJSONString();Files.write(out.resolve(id+"-selected.json"),raw.getBytes("UTF-8"));Files.write(out.resolve(id+"-serialized.json"),serialized.getBytes("UTF-8"));JSONObject v=LittleXSql.obj("id",id,"source_content_hex",r.getString(14),"java_content",props.getJSONObject("archetype").getString("content"),"serialized_json_utf8_hex",hex(serialized.getBytes("UTF-8")));String sql="INSERT INTO "+table+"(id,kind,arch_type,arch_module,fingerprint,root_id,src,dst,undirected,props,src_type,dst_type,seq)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE props=VALUES(props)";try(PreparedStatement w=c.prepareStatement(sql)){for(int k=1;k<=13;k++)w.setString(k,k==10?serialized:r.getString(k));try{w.executeUpdate();v.put("write","PASS");}catch(Throwable e){v.put("write","failed");v.put("error",e.toString());}}rows.add(v);}}}receipt.put("rows",rows);}Files.write(out.resolve("java-receipt.json"),receipt.toJSONString().getBytes("UTF-8"));System.exit(0);}
 static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02X",v&255));return s.toString();}
}
